-- ============================================================
--  Love Fellowship Ministry - MySQL Database Setup
--  Run this ONCE on a fresh MySQL instance, OR use EF Core:
--    dotnet ef migrations add InitialCreate
--    dotnet ef database update
-- ============================================================

CREATE DATABASE IF NOT EXISTS church_ministry CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE church_ministry;

-- ASP.NET Identity Tables (generated by EF Core - shown here for reference)
-- EF Core will auto-create these via db.Database.Migrate() in Program.cs

-- The tables below are custom (EF Core will also scaffold them automatically)

-- Ministry Groups
CREATE TABLE IF NOT EXISTS MinistryGroups (
  Id          INT AUTO_INCREMENT PRIMARY KEY,
  Name        VARCHAR(150) NOT NULL,
  Description TEXT,
  MeetingDay  VARCHAR(50),
  MeetingTime VARCHAR(50),
  Location    VARCHAR(200),
  LeaderId    INT,
  IsActive    TINYINT(1) DEFAULT 1,
  CreatedAt   DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- Members
CREATE TABLE IF NOT EXISTS Members (
  Id                INT AUTO_INCREMENT PRIMARY KEY,
  FirstName         VARCHAR(100) NOT NULL,
  LastName          VARCHAR(100) NOT NULL,
  Email             VARCHAR(255) NOT NULL UNIQUE,
  Phone             VARCHAR(30),
  AlternatePhone    VARCHAR(30),
  DateOfBirth       DATE,
  Gender            VARCHAR(20),
  MaritalStatus     VARCHAR(20),
  Address           TEXT,
  City              VARCHAR(100),
  Country           VARCHAR(100) DEFAULT 'Uganda',
  Occupation        VARCHAR(100),
  ProfilePhoto      VARCHAR(500),
  QrCode            LONGTEXT,
  JoinDate          DATETIME DEFAULT CURRENT_TIMESTAMP,
  BaptismDate       DATE,
  Status            VARCHAR(20) DEFAULT 'Active',
  MembershipType    VARCHAR(20) DEFAULT 'Regular',
  Notes             TEXT,
  EmergencyContact  VARCHAR(100),
  EmergencyPhone    VARCHAR(30),
  UserId            VARCHAR(450),
  MinistryGroupId   INT,
  FOREIGN KEY (MinistryGroupId) REFERENCES MinistryGroups(Id) ON DELETE SET NULL
);

-- Service Sessions
CREATE TABLE IF NOT EXISTS ServiceSessions (
  Id           INT AUTO_INCREMENT PRIMARY KEY,
  Title        VARCHAR(150) NOT NULL,
  ServiceType  VARCHAR(30) DEFAULT 'Sunday',
  ServiceDate  DATETIME NOT NULL,
  Speaker      VARCHAR(100),
  SermonTitle  VARCHAR(200),
  Notes        TEXT,
  IsActive     TINYINT(1) DEFAULT 1,
  CreatedAt    DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- Attendance Records
CREATE TABLE IF NOT EXISTS AttendanceRecords (
  Id               INT AUTO_INCREMENT PRIMARY KEY,
  MemberId         INT NOT NULL,
  ServiceSessionId INT NOT NULL,
  CheckInTime      DATETIME DEFAULT CURRENT_TIMESTAMP,
  CheckInMethod    VARCHAR(20) DEFAULT 'QR',
  Notes            TEXT,
  UNIQUE KEY uq_attendance (MemberId, ServiceSessionId),
  FOREIGN KEY (MemberId)         REFERENCES Members(Id) ON DELETE CASCADE,
  FOREIGN KEY (ServiceSessionId) REFERENCES ServiceSessions(Id) ON DELETE CASCADE
);

-- Givings
CREATE TABLE IF NOT EXISTS Givings (
  Id                INT AUTO_INCREMENT PRIMARY KEY,
  MemberId          INT,
  AnonymousName     VARCHAR(100),
  Amount            DECIMAL(18,2) NOT NULL,
  Currency          VARCHAR(10) DEFAULT 'UGX',
  GivingType        VARCHAR(30) DEFAULT 'Tithe',
  PaymentMethod     VARCHAR(30) NOT NULL,
  PaymentStatus     VARCHAR(20) DEFAULT 'Pending',
  TransactionId     VARCHAR(200),
  FlutterwaveRef    VARCHAR(200),
  PhoneNumber       VARCHAR(30),
  Notes             TEXT,
  IsRecurring       TINYINT(1) DEFAULT 0,
  RecurringInterval VARCHAR(20),
  GivingDate        DATETIME DEFAULT CURRENT_TIMESTAMP,
  NextGivingDate    DATETIME,
  FOREIGN KEY (MemberId) REFERENCES Members(Id) ON DELETE SET NULL
);

-- Sermons / Media
CREATE TABLE IF NOT EXISTS Sermons (
  Id               INT AUTO_INCREMENT PRIMARY KEY,
  Title            VARCHAR(200) NOT NULL,
  Description      TEXT,
  Speaker          VARCHAR(100),
  SeriesName       VARCHAR(150),
  SermonDate       DATETIME NOT NULL,
  VideoUrl         VARCHAR(1000),
  AudioUrl         VARCHAR(1000),
  ThumbnailUrl     VARCHAR(500),
  ScriptureReference VARCHAR(100),
  Tags             VARCHAR(500),
  IsLive           TINYINT(1) DEFAULT 0,
  LiveStreamUrl    VARCHAR(1000),
  IsPublished      TINYINT(1) DEFAULT 1,
  ViewCount        INT DEFAULT 0,
  CreatedAt        DATETIME DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE Sermons
  ADD COLUMN MeetingRoomCode VARCHAR(20) AFTER LiveStreamUrl,
  ADD COLUMN IsOnlineMeeting TINYINT(1)  DEFAULT 0 AFTER MeetingRoomCode;

-- Sermon Notes
CREATE TABLE IF NOT EXISTS SermonNotes (
  Id        INT AUTO_INCREMENT PRIMARY KEY,
  SermonId  INT NOT NULL,
  MemberId  INT NOT NULL,
  Note      TEXT NOT NULL,
  CreatedAt DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (SermonId) REFERENCES Sermons(Id) ON DELETE CASCADE,
  FOREIGN KEY (MemberId) REFERENCES Members(Id) ON DELETE CASCADE
);

-- Forum Posts
CREATE TABLE IF NOT EXISTS ForumPosts (
  Id               INT AUTO_INCREMENT PRIMARY KEY,
  Title            VARCHAR(200) NOT NULL,
  Content          TEXT NOT NULL,
  MemberId         INT NOT NULL,
  Category         VARCHAR(30) DEFAULT 'General',
  IsPastorQuestion TINYINT(1) DEFAULT 0,
  IsPinned         TINYINT(1) DEFAULT 0,
  IsApproved       TINYINT(1) DEFAULT 1,
  ViewCount        INT DEFAULT 0,
  CreatedAt        DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (MemberId) REFERENCES Members(Id) ON DELETE CASCADE
);

-- Forum Replies
CREATE TABLE IF NOT EXISTS ForumReplies (
  Id            INT AUTO_INCREMENT PRIMARY KEY,
  ForumPostId   INT NOT NULL,
  MemberId      INT NOT NULL,
  Content       TEXT NOT NULL,
  IsPastorReply TINYINT(1) DEFAULT 0,
  CreatedAt     DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (ForumPostId) REFERENCES ForumPosts(Id) ON DELETE CASCADE,
  FOREIGN KEY (MemberId)    REFERENCES Members(Id) ON DELETE CASCADE
);

-- Chat Messages
CREATE TABLE IF NOT EXISTS ChatMessages (
  Id       INT AUTO_INCREMENT PRIMARY KEY,
  MemberId INT NOT NULL,
  Message  TEXT NOT NULL,
  Room     VARCHAR(50) DEFAULT 'general',
  SentAt   DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (MemberId) REFERENCES Members(Id) ON DELETE CASCADE
);

-- Prayer Requests
CREATE TABLE IF NOT EXISTS PrayerRequests (
  Id               INT AUTO_INCREMENT PRIMARY KEY,
  MemberId         INT,
  AnonymousName    VARCHAR(100),
  Request          TEXT NOT NULL,
  IsAnonymous      TINYINT(1) DEFAULT 0,
  IsPublic         TINYINT(1) DEFAULT 1,
  IsAnswered       TINYINT(1) DEFAULT 0,
  AnswerTestimony  TEXT,
  Category         VARCHAR(30) DEFAULT 'General',
  PrayerCount      INT DEFAULT 0,
  CreatedAt        DATETIME DEFAULT CURRENT_TIMESTAMP,
  AnsweredAt       DATETIME,
  FOREIGN KEY (MemberId) REFERENCES Members(Id) ON DELETE SET NULL
);

-- Prayer Interactions
CREATE TABLE IF NOT EXISTS PrayerInteractions (
  Id              INT AUTO_INCREMENT PRIMARY KEY,
  PrayerRequestId INT NOT NULL,
  MemberId        INT,
  Type            VARCHAR(20) DEFAULT 'prayed',
  Comment         TEXT,
  CreatedAt       DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (PrayerRequestId) REFERENCES PrayerRequests(Id) ON DELETE CASCADE,
  FOREIGN KEY (MemberId)        REFERENCES Members(Id) ON DELETE SET NULL
);

-- Newsletters
CREATE TABLE IF NOT EXISTS Newsletters (
  Id             INT AUTO_INCREMENT PRIMARY KEY,
  Subject        VARCHAR(200) NOT NULL,
  Body           LONGTEXT NOT NULL,
  PreviewText    VARCHAR(300),
  Status         VARCHAR(20) DEFAULT 'Draft',
  SentAt         DATETIME,
  RecipientsCount INT DEFAULT 0,
  CreatedAt      DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- Newsletter Subscribers
CREATE TABLE IF NOT EXISTS NewsletterSubscribers (
  Id               INT AUTO_INCREMENT PRIMARY KEY,
  Email            VARCHAR(255) NOT NULL UNIQUE,
  Name             VARCHAR(150),
  IsActive         TINYINT(1) DEFAULT 1,
  SubscribedAt     DATETIME DEFAULT CURRENT_TIMESTAMP,
  UnsubscribeToken VARCHAR(100)
);

-- Church Events
CREATE TABLE IF NOT EXISTS ChurchEvents (
  Id                   INT AUTO_INCREMENT PRIMARY KEY,
  Title                VARCHAR(200) NOT NULL,
  Description          TEXT,
  StartDate            DATETIME NOT NULL,
  EndDate              DATETIME NOT NULL,
  Location             VARCHAR(300),
  ImageUrl             VARCHAR(500),
  IsPublic             TINYINT(1) DEFAULT 1,
  RequiresRegistration TINYINT(1) DEFAULT 0,
  MaxCapacity          INT,
  TicketPrice          DECIMAL(18,2),
  CreatedAt            DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- Event Registrations
CREATE TABLE IF NOT EXISTS EventRegistrations (
  Id           INT AUTO_INCREMENT PRIMARY KEY,
  EventId      INT NOT NULL,
  MemberId     INT,
  Name         VARCHAR(200) NOT NULL,
  Email        VARCHAR(255) NOT NULL,
  Phone        VARCHAR(30),
  RegisteredAt DATETIME DEFAULT CURRENT_TIMESTAMP,
  IsConfirmed  TINYINT(1) DEFAULT 1,
  FOREIGN KEY (EventId)  REFERENCES ChurchEvents(Id) ON DELETE CASCADE,
  FOREIGN KEY (MemberId) REFERENCES Members(Id) ON DELETE SET NULL
);

-- Notifications
CREATE TABLE IF NOT EXISTS Notifications (
  Id        INT AUTO_INCREMENT PRIMARY KEY,
  MemberId  INT,
  Title     VARCHAR(200),
  Message   TEXT,
  Link      VARCHAR(500),
  IsRead    TINYINT(1) DEFAULT 0,
  CreatedAt DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (MemberId) REFERENCES Members(Id) ON DELETE CASCADE
);

