SELECT 'Database setup complete! Now run: dotnet ef migrations add InitialCreate && dotnet ef database update' AS Status;

-- ── Meeting Rooms ──────────────────────────────────────────
CREATE TABLE IF NOT EXISTS MeetingRooms (
  Id                  INT AUTO_INCREMENT PRIMARY KEY,
  Title               VARCHAR(200) NOT NULL,
  Description         TEXT,
  MeetingType         VARCHAR(30) DEFAULT 'Prayer',
  RoomCode            VARCHAR(20) NOT NULL UNIQUE,
  HostUserId          VARCHAR(450),
  HostMemberId        INT,
  ScheduledAt         DATETIME,
  StartedAt           DATETIME,
  EndedAt             DATETIME,
  Status              VARCHAR(20) DEFAULT 'Scheduled',
  IsRecurring         TINYINT(1) DEFAULT 0,
  RecurringPattern    VARCHAR(100),
  WaitingRoomEnabled  TINYINT(1) DEFAULT 1,
  ChatEnabled         TINYINT(1) DEFAULT 1,
  RecordingEnabled    TINYINT(1) DEFAULT 0,
  MaxParticipants     INT DEFAULT 50,
  IsPublic            TINYINT(1) DEFAULT 1,
  PassCode            VARCHAR(50),
  CreatedAt           DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (HostMemberId) REFERENCES Members(Id) ON DELETE SET NULL
);

-- ── Meeting Participants ───────────────────────────────────
CREATE TABLE IF NOT EXISTS MeetingParticipants (
  Id              INT AUTO_INCREMENT PRIMARY KEY,
  MeetingRoomId   INT NOT NULL,
  MemberId        INT,
  DisplayName     VARCHAR(150) NOT NULL,
  ConnectionId    VARCHAR(200),
  IsHost          TINYINT(1) DEFAULT 0,
  IsCoHost        TINYINT(1) DEFAULT 0,
  IsMuted         TINYINT(1) DEFAULT 0,
  IsVideoOff      TINYINT(1) DEFAULT 0,
  IsHandRaised    TINYINT(1) DEFAULT 0,
  IsInWaitingRoom TINYINT(1) DEFAULT 0,
  IsAdmitted      TINYINT(1) DEFAULT 1,
  JoinedAt        DATETIME DEFAULT CURRENT_TIMESTAMP,
  LeftAt          DATETIME,
  FOREIGN KEY (MeetingRoomId) REFERENCES MeetingRooms(Id) ON DELETE CASCADE,
  FOREIGN KEY (MemberId)      REFERENCES Members(Id) ON DELETE SET NULL
);

-- ── Meeting Messages ───────────────────────────────────────
CREATE TABLE IF NOT EXISTS MeetingMessages (
  Id            INT AUTO_INCREMENT PRIMARY KEY,
  MeetingRoomId INT NOT NULL,
  MemberId      INT,
  SenderName    VARCHAR(150) NOT NULL,
  Message       TEXT NOT NULL,
  Type          VARCHAR(20) DEFAULT 'chat',
  SentAt        DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (MeetingRoomId) REFERENCES MeetingRooms(Id) ON DELETE CASCADE,
  FOREIGN KEY (MemberId)      REFERENCES Members(Id) ON DELETE SET NULL
);

-- ── EventRegistrations Add Columns ───────────────────────────────────────
ALTER TABLE EventRegistrations
  ADD COLUMN PaymentStatus   VARCHAR(20)    DEFAULT 'Free'  AFTER IsConfirmed,
  ADD COLUMN TransactionId   VARCHAR(200)                   AFTER PaymentStatus,
  ADD COLUMN FlutterwaveRef  VARCHAR(200)                   AFTER TransactionId,
  ADD COLUMN AmountPaid      DECIMAL(18,2)  DEFAULT 0       AFTER FlutterwaveRef,
  ADD COLUMN PaidAt          DATETIME                       AFTER AmountPaid;

  ALTER TABLE ChurchEvents
  ADD COLUMN IsAllDay            TINYINT(1)    DEFAULT 0    AFTER EndDate,
  ADD COLUMN AllowPartialPayment TINYINT(1)    DEFAULT 0    AFTER IsAllDay,
  ADD COLUMN MinPartialAmount    DECIMAL(18,2)              AFTER AllowPartialPayment,
  ADD COLUMN RichDescription     LONGTEXT                   AFTER Description,
  ADD COLUMN GalleryJson         JSON                       AFTER RichDescription;

ALTER TABLE EventRegistrations
  ADD COLUMN TotalAmount  DECIMAL(18,2) DEFAULT 0  AFTER AmountPaid,
  ADD COLUMN IsBehalf     TINYINT(1)    DEFAULT 0  AFTER TotalAmount,
  ADD COLUMN BehalfName   VARCHAR(200)             AFTER IsBehalf,
  ADD COLUMN BehalfEmail  VARCHAR(255)             AFTER BehalfName,
  ADD COLUMN BehalfPhone  VARCHAR(30)              AFTER BehalfEmail,
  ADD COLUMN BehalfNotes  TEXT                     AFTER BehalfPhone;

CREATE TABLE IF NOT EXISTS EventPayments (
  Id                   INT AUTO_INCREMENT PRIMARY KEY,
  EventRegistrationId  INT NOT NULL,
  Amount               DECIMAL(18,2) NOT NULL,
  TransactionId        VARCHAR(200),
  FlutterwaveRef       VARCHAR(200),
  Status               VARCHAR(20) DEFAULT 'Pending',
  PaymentMethod        VARCHAR(50),
  CreatedAt            DATETIME DEFAULT CURRENT_TIMESTAMP,
  PaidAt               DATETIME,
  Notes                TEXT,
  FOREIGN KEY (EventRegistrationId)
      REFERENCES EventRegistrations(Id) ON DELETE CASCADE
);